void solve(int n, int row, vector<int>& cols, vector<bool>& col, vector<bool>& diag1, vector<bool>& diag2) {
    if (row == n) {
        for (int c : cols) cout << c + 1 << " ";
        cout << endl;
        return;
    }
    for (int c = 0; c < n; ++c) {
        int d1 = row - c + n - 1, d2 = row + c;
        if (col[c] || diag1[d1] || diag2[d2]) continue;
        col[c] = diag1[d1] = diag2[d2] = true;
        cols.push_back(c);
        solve(n, row + 1, cols, col, diag1, diag2);
        cols.pop_back();
        col[c] = diag1[d1] = diag2[d2] = false;
    }
}
int main() {
    int n;
    cin >> n;
    if (n < 1) return 0;
    vector<int> cols;
    vector<bool> col(n, false), diag1(2 * n - 1, false), diag2(2 * n - 1, false);
    solve(n, 0, cols, col, diag1, diag2);
    return 0;
}

