const string mp[] = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
void dfs(const string& digits, int idx, string& cur, vector<string>& res) {
    if (idx == (int)digits.size()) {
        res.push_back(cur);
        return;
    }
    for (char ch : mp[digits[idx] - '0']) {
        cur.push_back(ch);
        dfs(digits, idx + 1, cur, res);
        cur.pop_back();
    }
}
