    int n, m;
    cin >> n >> m;
    vector<vector<int>> maze(n, vector<int>(m));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) cin >> maze[i][j];
    if (maze[0][0] == 1 || maze[n-1][m-1] == 1) { cout << -1 << endl; return 0; }
    vector<vector<bool>> vis(n, vector<bool>(m, false));
    queue<tuple<int,int,int>> q;
    q.push({0, 0, 0});
    vis[0][0] = true;
    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};
    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (x == n - 1 && y == m - 1) { cout << d << endl; return 0; }
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !vis[nx][ny] && maze[nx][ny] == 0) {
                vis[nx][ny] = true;
                q.push({nx, ny, d + 1});
            }
        }
    }
    cout << -1 << endl;
    return 0;
}

