using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        ++indeg[v];
    }
    queue<int> q;
    for (int i = 1; i <= n; ++i) if (indeg[i] == 0) q.push(i);
    vector<int> ans;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ans.push_back(u);
        for (int v : g[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }
    if ((int)ans.size() != n) cout << "图中存在环" << endl;
    else {
        for (int i = 0; i < n; ++i) cout << ans[i] << (i + 1 == n ? '
' : ' ');
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> f;
    DSU(int n): f(n + 1) { iota(f.begin(), f.end(), 0); }
    int find(int x) { return f[x] == x ? x : f[x] = find(f[x]); }
    bool unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        f[ra] = rb;
        return true;
    }
};
int main() {
    int n, m;
    cin >> n >> m;
    DSU dsu(n);
    bool hasCycle = false;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        if (!dsu.unite(u, v)) hasCycle = true;
    }
    cout << (hasCycle ? "存在环" : "不存在环") << endl;
    return 0;
}

