#include <bits/stdc++.h>
using namespace std;
struct Node {
    int val;
    Node *l, *r;
    Node(int x): val(x), l(nullptr), r(nullptr) {}
};
Node* insert(Node* root, int x) {
    if (!root) return new Node(x);
    if (x < root->val) root->l = insert(root->l, x);
    else if (x > root->val) root->r = insert(root->r, x);
    return root;
}
bool search(Node* root, int x) {
    if (!root) return false;
    if (root->val == x) return true;
    if (x < root->val) return search(root->l, x);
    return search(root->r, x);
}
int main() {
    Node* root = nullptr;
    vector<int> a = {5, 3, 7, 1, 4, 6, 8};
    for (int x : a) root = insert(root, x);
    cout << (search(root, 4) ? "找到 4" : "未找到 4") << endl;
    cout << (search(root, 9) ? "找到 9" : "未找到 9") << endl;
    return 0;
}

