#include <bits/stdc++.h>
using namespace std;
struct TreeNode {
    int val;
    TreeNode *l, *r;
    TreeNode(int x): val(x), l(nullptr), r(nullptr) {}
};
int height(TreeNode* root) {
    if (!root) return 0;
    int lh = height(root->l);
    if (lh == -1) return -1;
    int rh = height(root->r);
    if (rh == -1) return -1;
    if (abs(lh - rh) > 1) return -1;
    return max(lh, rh) + 1;
}
bool isBalanced(TreeNode* root) {
    return height(root) != -1;
}
int main() {
    TreeNode* root = new TreeNode(1);
    root->l = new TreeNode(2);
    root->r = new TreeNode(3);
    root->l->l = new TreeNode(4);
    cout << (isBalanced(root) ? "平衡" : "不平衡") << endl;
    return 0;
}

