#include <bits/stdc++.h>
using namespace std;
int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}
int applyOp(int a, int b, char op) {
    if (op == '+') return a + b;
    if (op == '-') return a - b;
    if (op == '*') return a * b;
    if (op == '/' && b != 0) return a / b;
    return 0;
}
int evaluate(const string& expr) {
    stack<int> values;
    stack<char> ops;
    int n = expr.size();
    for (int i = 0; i < n; ++i) {
        if (expr[i] == ' ') continue;
        if (isdigit(expr[i])) {
            int val = 0;
            while (i < n && isdigit(expr[i])) { val = val * 10 + (expr[i] - '0'); ++i; }
            values.push(val);
            --i;
        } else if (expr[i] == '(') ops.push(expr[i]);
        else if (expr[i] == ')') {
            while (!ops.empty() && ops.top() != '(') {
                int b = values.top(); values.pop();
                int a = values.top(); values.pop();
                values.push(applyOp(a, b, ops.top())); ops.pop();
            }
            if (!ops.empty()) ops.pop();
        } else {
            while (!ops.empty() && precedence(ops.top()) >= precedence(expr[i])) {
                int b = values.top(); values.pop();
                int a = values.top(); values.pop();
                values.push(applyOp(a, b, ops.top())); ops.pop();
            }
            ops.push(expr[i]);
        }
    }
    while (!ops.empty()) {
        int b = values.top(); values.pop();
        int a = values.top(); values.pop();
        values.push(applyOp(a, b, ops.top())); ops.pop();
    }
    return values.top();
}
int main() {
    string expr;
    getline(cin, expr);
    cout << evaluate(expr) << endl;
    return 0;
}

