    Library lib;
    lib.addBook("978-7-111", "C++ Primer", "Stanley Lippman");
    lib.addBook("978-7-222", "Effective C++", "Scott Meyers");
    lib.findBook("978-7-111");
    lib.findBook("000-0-000");
    return 0;
}

